class LRUCache {
  constructor(capacidad) {
    this.cap = capacidad;
    this.map = new Map();
  }
  get(clave) {
    if (!this.map.has(clave)) return -1;
    const v = this.map.get(clave);
    this.map.delete(clave);
    this.map.set(clave, v);
    return v;
  }
  put(clave, valor) {
    this.map.delete(clave);
    this.map.set(clave, valor);
    if (this.map.size > this.cap) this.map.delete(this.map.keys().next().value);
  }
}

function simularLRU(capacidad, operaciones) {
  const cache = new LRUCache(capacidad);
  return operaciones.map(([op, k, v]) => (op === "get" ? cache.get(k) : (cache.put(k, v), null)));
}

