from collections import OrderedDict

class LRUCache:
    def __init__(self, capacidad):
        self.cap = capacidad
        self.d = OrderedDict()

    def get(self, clave):
        if clave not in self.d:
            return -1
        self.d.move_to_end(clave)
        return self.d[clave]

    def put(self, clave, valor):
        self.d[clave] = valor
        self.d.move_to_end(clave)
        if len(self.d) > self.cap:
            self.d.popitem(last=False)


def simularLRU(capacidad, operaciones):
    cache = LRUCache(capacidad)
    res = []
    for op in operaciones:
        if op[0] == "get":
            res.append(cache.get(op[1]))
        else:
            cache.put(op[1], op[2])
            res.append(None)
    return res
